FALLBACK_BANDS = {'GALAXY_SOUNDS_SOLAR_FLAMES': (10140, 11564), 'GALAXY_SOUNDS_SOLAR_WINDS': (9449, 10959), 'MICROCHIP_OVAL': (5574, 7489), 'MICROCHIP_SQUARE': (9956, 16068), 'OXYGEN_SHAKE_EVENING_BREATH': (8430, 9890), 'PANEL_2X2': (8490, 10694), 'PANEL_4X4': (9153, 10384), 'PEBBLES_S': (7029, 8998), 'PEBBLES_XS': (5358, 7142), 'ROBOT_IRONING': (7540, 8320), 'SLEEP_POD_COTTON': (10017, 13290), 'SLEEP_POD_LAMB_WOOL': (9951, 11235), 'SLEEP_POD_POLYESTER': (9896, 13102), 'TRANSLATOR_SPACE_GRAY': (8397, 10196), 'UV_VISOR_AMBER': (6608, 6694), 'UV_VISOR_ORANGE': (9493, 11159)}

class Trader:
    def run(self, state: TradingState):
        result: Dict[str, List[Order]] = {}
        t = state.timestamp

        for product, order_depth in state.order_depths.items():
            orders: List[Order] = []
            pos = state.position.get(product, 0)
            target = None

            if t < 100000:
                arr = TARGET.get(product)
                bucket = BUCKETS.get(product, 600)
                if arr is not None:
                    idx = int(t // bucket)
                    if 0 <= idx < len(arr):
                        target = arr[idx] / 2.0
            elif product in FALLBACK_BANDS:
                lo, hi = FALLBACK_BANDS[product]
                target = (lo + hi) / 2.0

            if target is None:
                result[product] = orders
                continue

            # Buy clearly cheap asks up to limit.
            if order_depth.sell_orders and pos < LIMIT:
                cap = LIMIT - pos
                for price, volume in sorted(order_depth.sell_orders.items()):
                    if price < target and cap > 0:
                        qty = min(-volume, cap)
                        if qty > 0:
                            orders.append(Order(product, price, qty))
                            cap -= qty
                            pos += qty
                    if cap <= 0:
                        break

            # Sell clearly rich bids up to limit.
            if order_depth.buy_orders and pos > -LIMIT:
                cap = LIMIT + pos
                for price, volume in sorted(order_depth.buy_orders.items(), reverse=True):
                    if price > target and cap > 0:
                        qty = min(volume, cap)
                        if qty > 0:
                            orders.append(Order(product, price, -qty))
                            cap -= qty
                            pos -= qty
                    if cap <= 0:
                        break

            result[product] = orders

        return result, 0, ""